const supported = ["tiktok", "instagram", "youtube"];
const privacyLevels = [
  "SELF_ONLY",
  "MUTUAL_FOLLOW_FRIENDS",
  "FOLLOWER_OF_CREATOR",
  "PUBLIC_TO_EVERYONE",
];
function handle(value) {
  return typeof value === "string" ? value.trim().replace(/^@/, "").toLowerCase() : "";
}

function directVideo(value) {
  if (typeof value !== "string" || value.length > 1900) return false;
  const match = /^https:\/\/([a-z0-9.-]+)\/[^\s<>"'|#\\?]*\.mp4(?:\?[^\s<>"'|#\\]*)?$/i.exec(value);
  return Boolean(
    match &&
    /^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$/i.test(match[1]) &&
    !/\.(?:local|internal|localhost|test|onion)$/i.test(match[1]),
  );
}

function planPublication(settings) {
  const {
    confirm,
    idea,
    brand_voice,
    video_url,
    brand_id,
    publication_key,
    tiktok_privacy,
    platforms,
    expected_accounts,
  } = settings;
  if (confirm !== true)
    throw new Error(
      "Set confirm to true only after reviewing the selected publishing configuration.",
    );
  if (
    typeof idea !== "string" ||
    !idea.trim() ||
    idea.length > 4000 ||
    typeof brand_voice !== "string" ||
    brand_voice.length > 1500 ||
    !directVideo(video_url)
  )
    throw new Error("Provide an idea and an approved direct HTTPS MP4 URL.");
  if (
    typeof brand_id !== "string" ||
    !/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(brand_id) ||
    typeof publication_key !== "string" ||
    !/^[A-Za-z0-9_-]{16,100}$/.test(publication_key) ||
    publication_key.startsWith("YOUR_")
  ) {
    throw new Error("Set a PostWire brand ID and a stable, unique publication key.");
  }
  if (
    !Array.isArray(platforms) ||
    !platforms.length ||
    platforms.some((platform) => !supported.includes(platform)) ||
    new Set(platforms).size !== platforms.length
  )
    throw new Error("Select unique platforms from TikTok, Instagram and YouTube.");
  const accounts = {};
  for (const platform of platforms) {
    const expected = handle(expected_accounts?.[platform]);
    if (
      !expected ||
      expected.length > 160 ||
      /[<>\s\/\\]/.test(expected) ||
      expected.startsWith("your_")
    )
      throw new Error("Set the expected handle for " + platform + ".");
    accounts[platform] = expected;
  }
  if (platforms.includes("tiktok") && !privacyLevels.includes(tiktok_privacy))
    throw new Error("Select a documented TikTok privacy level.");
  return {
    platforms,
    accounts,
    video_url,
    brand_id: brand_id.toLowerCase(),
    publication_key,
    tiktok_privacy,
    generation: { prompt: idea, platforms, media_url: video_url, brand_voice },
  };
}

export default ({ settings }) => ({ plan: planPublication(settings) });

