function checkBrand(plan, body) {
  const brand = body?.brand;
  if (brand?.id !== plan.brand_id || !Array.isArray(brand.accounts))
    throw new Error("PostWire did not confirm the configured brand.");
  for (const platform of plan.platforms) {
    const found = brand.accounts.filter((account) => account.platform === platform);
    if (
      found.length !== 1 ||
      handle(found[0].handle) !== plan.accounts[platform] ||
      found[0].needs === "reconnect" ||
      (Array.isArray(found[0].needs) && found[0].needs.length)
    ) {
      throw new Error("PostWire did not confirm the intended account for " + platform + ".");
    }
  }
}

function checkCreator(plan, body) {
  if (
    body?.ok !== true ||
    body.brand_id !== plan.brand_id ||
    handle(body.creator_username) !== plan.accounts.tiktok ||
    !Array.isArray(body.privacy_level_options) ||
    !body.privacy_level_options.includes(plan.tiktok_privacy)
  ) {
    throw new Error("The TikTok account does not confirm the selected privacy level.");
  }
}

function buildPublish(plan, body) {
  const drafts = body?.drafts;
  if (
    !drafts ||
    typeof drafts !== "object" ||
    Array.isArray(drafts) ||
    Object.keys(drafts).length !== plan.platforms.length
  ) {
    throw new Error("PostWire did not return one caption for every selected platform.");
  }
  const per_platform = {},
    options = {};
  for (const platform of plan.platforms) {
    const draft = drafts[platform];
    if (!draft || typeof draft.text !== "string" || !draft.text.trim())
      throw new Error("Missing native caption for " + platform + ".");
    per_platform[platform] = { text: draft.text };
    if (platform === "tiktok") options.tiktok = { privacy_level: plan.tiktok_privacy };
    if (platform === "youtube") {
      if (draft.title !== undefined) {
        if (typeof draft.title !== "string" || !draft.title.trim() || [...draft.title].length > 100)
          throw new Error("Invalid YouTube title.");
        per_platform.youtube.title = draft.title;
      }
      if (draft.tags !== undefined) {
        if (
          !Array.isArray(draft.tags) ||
          draft.tags.some((tag) => typeof tag !== "string" || !tag.trim())
        )
          throw new Error("Invalid YouTube tags.");
        options.youtube = { tags: draft.tags };
      }
    }
  }
  return {
    platforms: plan.platforms,
    video_url: plan.video_url,
    per_platform,
    options,
    brand_id: plan.brand_id,
    idempotency_key: plan.publication_key,
  };
}

function handle(value) {
  return typeof value === "string" ? value.trim().replace(/^@/, "").toLowerCase() : "";
}

function receiptUrl(url, platform) {
  if (typeof url !== "string" || url.length > 1800) return null;
  const match = /^https:\/\/([a-z0-9.-]+)\/[^\s<>"'|\\]*$/i.exec(url);
  const domains = {
    instagram: ["instagram.com"],
    tiktok: ["tiktok.com"],
    youtube: ["youtube.com", "youtu.be"],
  };
  const host = match?.[1]?.toLowerCase();
  return host && domains[platform].some((root) => host === root || host.endsWith("." + root))
    ? url
    : null;
}

function receiptId(value) {
  return typeof value === "string" && /^[A-Za-z0-9_.:-]{1,240}$/.test(value) ? value : null;
}

function publishResult(plan, status, body) {
  const errorText = (value) =>
    typeof value === "string" && value.trim() ? value.trim().slice(0, 1000) : null;
  const details = (state, code = null, error = null) =>
    plan.platforms.map((platform) => ({
      platform,
      account: plan.accounts[platform],
      state,
      code,
      error,
    }));
  const finish = (state, results, jobId = null) => {
    const [count, accepted] = ["posted", "accepted"].map(
      (value) => results.filter((row) => row.state === value).length,
    );
    return {
      state,
      publication_key: plan.publication_key,
      posted: count,
      accepted,
      job_id: jobId,
      status_lookup: jobId
        ? "https://postwire.io/api/post/status?id=" + encodeURIComponent(jobId)
        : null,
      results,
    };
  };
  const errorCode = receiptId(body?.code);
  if (status === 409 && errorCode === "duplicate_post")
    return finish("duplicate", details("duplicate", errorCode, errorText(body.error)));
  if (
    [400, 401, 402, 403, 404, 413, 429].includes(status) ||
    (status === 409 && errorCode === "ambiguous_brand") ||
    (status === 503 && errorCode === "governance_unavailable")
  )
    return finish("rejected", details("failed", errorCode, errorText(body?.error)));
  if (![200, 202].includes(status) || !Array.isArray(body?.results))
    return finish("unconfirmed", details("unconfirmed"));
  if (
    body.results.some((row) => !plan.platforms.includes(row?.platform)) ||
    new Set(body.results.map((row) => row.platform)).size !== body.results.length
  )
    return finish("unconfirmed", details("unconfirmed"));
  const approvalJob =
    status === 202 && body.ok === true && body.status === "pending_approval" && body.posted === 0
      ? receiptId(body.id)
      : null;
  if (status === 202 && !approvalJob) return finish("unconfirmed", details("unconfirmed"));
  const rows = plan.platforms.map((platform) => {
    const match = body.results.find((data) => data.platform === platform);
    const account = plan.accounts[platform];
    const row = {
      platform,
      account,
      state: "unconfirmed",
      code: receiptId(match?.code),
      error: errorText(match?.error),
    };
    if (!match) return row;
    const correct =
      match.account?.platform === platform &&
      match.account?.brand_id === plan.brand_id &&
      handle(match.account?.handle) === account;
    if (match.account && !correct) return row;
    if (match.ok === false) {
      if (status === 202 && match.status === "pending_approval" && correct)
        return { ...row, state: "pending_approval" };
      if (status === 200 && (match.status === "held" || row.code === "networks_per_post"))
        return { ...row, state: "held" };
      if (status === 200 && typeof match.error === "string") return { ...row, state: "failed" };
      return row;
    }
    if (status !== 200 || match.ok !== true || !correct) return row;
    const id = receiptId(match.id);
    const url = receiptUrl(match.url, platform);
    if (!id) return row;
    const acknowledged = {
      ...row,
      id,
      url,
      status_lookup:
        "https://postwire.io/api/post/status?platform=" +
        platform +
        "&id=" +
        encodeURIComponent(id),
    };
    if (match.status === "failed" || match.status === "rejected") return row;
    if (match.status === "processing" || match.status === "scheduled" || !url)
      return { ...acknowledged, state: "accepted" };
    return { ...acknowledged, state: "posted" };
  });
  if (rows.some((row) => row.state === "unconfirmed"))
    return finish("unconfirmed", rows, approvalJob);
  if (approvalJob) return finish("pending_approval", rows, approvalJob);
  if (rows.every((row) => row.state === "posted")) return finish("posted", rows);
  if (rows.every((row) => row.state === "posted" || row.state === "accepted"))
    return finish("accepted", rows);
  if (rows.some((row) => row.state === "posted" || row.state === "accepted"))
    return finish("partial", rows);
  if (rows.every((row) => row.state === "held")) return finish("held", rows);
  return finish("failed", rows);
}

export default async ({ plan, token }, context) => {
  if (typeof token !== "string" || !token.trim()) throw new Error("Connect a PostWire API key.");
  const base = "https://postwire.io";
  const call = async (path, method, body) => {
    const response = await context.fetch(base + path, {
      method,
      headers: {
        authorization: "Bearer " + token,
        ...(body ? { "content-type": "application/json" } : {}),
      },
      ...(body ? { body: JSON.stringify(body) } : {}),
    });
    return { status: response.status, body: await response.json().catch(() => null) };
  };
  const brand = await call("/api/brands/" + plan.brand_id, "GET");
  if (brand.status !== 200) throw new Error("Could not read the configured PostWire brand.");
  checkBrand(plan, brand.body);
  if (plan.platforms.includes("tiktok")) {
    const checked = await call(
      "/api/tiktok/creator-info?brand_id=" + encodeURIComponent(plan.brand_id),
      "GET",
    );
    if (checked.status !== 200) throw new Error("Could not read the TikTok creator account.");
    checkCreator(plan, checked.body);
  }
  const draft = await call("/api/generate", "POST", plan.generation);
  if (draft.status !== 200) throw new Error("PostWire could not generate the native captions.");
  const request = buildPublish(plan, draft.body);
  try {
    const published = await call("/api/post", "POST", request);
    return { result: publishResult(plan, published.status, published.body) };
  } catch {
    return { result: publishResult(plan, 0, null) };
  }
};
